package android.graphics;public class Paint {public static final int ANTI_ALIAS_FLAG=1,SUBPIXEL_TEXT_FLAG=128;public static class FontMetrics {public float top,ascent,descent,bottom,leading;}private Typeface typeface=Typeface.DEFAULT;private float size=12;int color=Color.BLACK;private static final java.awt.font.FontRenderContext FRC=new java.awt.font.FontRenderContext(null,true,true);public Paint(){}public Paint(int flags){}public void setTypeface(Typeface t){typeface=t==null?Typeface.DEFAULT:t;}public void setTextSize(float s){size=s;}public void setColor(int c){color=c;}java.awt.Font font(){return typeface.font.deriveFont(size);}public FontMetrics getFontMetrics(){java.awt.font.LineMetrics m=font().getLineMetrics("Hg",FRC);FontMetrics f=new FontMetrics();f.ascent=-m.getAscent();f.descent=m.getDescent();f.leading=m.getLeading();f.top=f.ascent;f.bottom=f.descent;return f;}public float measureText(String s){return s.isEmpty()?0:(float)font().getStringBounds(s,FRC).getWidth();}public float measureText(String s,int start,int end){return measureText(s.substring(start,end));}public int breakText(String s,int start,int end,boolean forward,float max,float[] measured){int n=0;while(start+n<end&&measureText(s,start,start+n+1)<=max)n++;return n;}}
